-- DistribDZ initial PostgreSQL schema and baseline dataset.
-- Safe to re-run: tables/indexes and seed rows are idempotent.

CREATE TABLE IF NOT EXISTS wilayas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL UNIQUE, name_ar TEXT NOT NULL, region TEXT NOT NULL, latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, is_active BOOLEAN NOT NULL DEFAULT FALSE, priority_order INTEGER NOT NULL DEFAULT 99, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());

CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, full_name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','producer')), company_name TEXT, sector TEXT, phone TEXT, preferred_wilaya_id BIGINT REFERENCES wilayas(id) ON DELETE SET NULL, preferred_store_types TEXT NOT NULL DEFAULT '["superette","magasin_gros"]', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());

CREATE TABLE IF NOT EXISTS user_territories (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, wilaya_id BIGINT NOT NULL REFERENCES wilayas(id) ON DELETE CASCADE, PRIMARY KEY(user_id,wilaya_id));

CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());

CREATE TABLE IF NOT EXISTS stores (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, normalized_key TEXT NOT NULL UNIQUE, wilaya_id BIGINT NOT NULL REFERENCES wilayas(id) ON DELETE RESTRICT, store_type TEXT NOT NULL CHECK(store_type IN ('superette','mini_market','epicerie','magasin_gros','hypermarche','autre')), address TEXT, phone TEXT, latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, rating DOUBLE PRECISION, review_count INTEGER NOT NULL DEFAULT 0, opening_hours TEXT, google_maps_url TEXT, main_products TEXT, approx_surface_m2 INTEGER, clientele_type TEXT, photo_url TEXT, source TEXT NOT NULL DEFAULT 'Google Maps', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());

CREATE INDEX IF NOT EXISTS idx_stores_wilaya ON stores(wilaya_id);

CREATE INDEX IF NOT EXISTS idx_stores_type ON stores(store_type);

CREATE INDEX IF NOT EXISTS idx_stores_rating ON stores(rating);

CREATE TABLE IF NOT EXISTS leads (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, store_id BIGINT NOT NULL REFERENCES stores(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN ('interesse','contacte','client','non_interesse')), notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id,store_id));

CREATE TABLE IF NOT EXISTS lead_history (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, lead_id BIGINT NOT NULL REFERENCES leads(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL, note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());

CREATE TABLE IF NOT EXISTS scraping_jobs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_by BIGINT REFERENCES users(id) ON DELETE SET NULL, wilaya_ids_json TEXT NOT NULL, categories_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('termine','en_cours','erreur')), found_count INTEGER NOT NULL DEFAULT 0, inserted_count INTEGER NOT NULL DEFAULT 0, duplicate_count INTEGER NOT NULL DEFAULT 0, log_summary TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), completed_at TIMESTAMPTZ);

ON CONFLICT(code) DO NOTHING;

